arguments.content:
/* WellStream Platform — Global Styles */
:root {
  --navy: #15295A;
  --navy-dark: #0D1B3E;
  --navy-light: #1E3570;
  --green: #6CC24A;
  --green-dark: #52A034;
  --gray-dark: #3C424B;
  --gray-mid: #6B7280;
  --gray-light: #9CA3AF;
  --surface: #1B2340;
  --surface-2: #222B45;
  --surface-3: #2A3558;
  --text: #F0F4FF;
  --text-muted: #A8B4CC;
  --border: rgba(108, 194, 74, 0.15);
  --border-subtle: rgba(255,255,255,0.08);
  --accent: #6CC24A;
  --white: #ffffff;
  --font: 'Inter', system-ui, -apple-system, sans-serif;
}

*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

html { scroll-behavior: smooth; }

body {
  font-family: var(--font);
  background: var(--navy-dark);
  color: var(--text);
  line-height: 1.6;
  font-size: 16px;
}

/* Typography */
h1, h2, h3, h4, h5, h6 { font-weight: 700; line-height: 1.2; }
h1 { font-size: clamp(2rem, 5vw, 3.5rem); }
h2 { font-size: clamp(1.75rem, 3.5vw, 2.5rem); }
h3 { font-size: clamp(1.25rem, 2.5vw, 1.75rem); }
h4 { font-size: 1.125rem; }
p { color: var(--text-muted); line-height: 1.7; }

a { color: inherit; text-decoration: none; }

/* Layout */
.container { max-width: 1200px; margin: 0 auto; padding: 0 1.5rem; }
.section { padding: 5rem 0; }
.section-sm { padding: 3rem 0; }

/* Buttons */
.btn {
  display: inline-flex; align-items: center; gap: 0.5rem;
  padding: 0.75rem 1.75rem;
  border-radius: 4px;
  font-weight: 600; font-size: 0.9rem; letter-spacing: 0.02em;
  cursor: pointer; transition: all 0.2s ease;
  border: none; text-decoration: none;
}
.btn-primary {
  background: var(--green); color: var(--navy-dark);
}
.btn-primary:hover { background: var(--green-dark); transform: translateY(-1px); }
.btn-outline {
  background: transparent; color: var(--white);
  border: 2px solid rgba(255,255,255,0.4);
}
.btn-outline:hover { border-color: var(--green); color: var(--green); }
.btn-ghost {
  background: transparent; color: var(--green);
  border: 2px solid var(--green);
}
.btn-ghost:hover { background: var(--green); color: var(--navy-dark); }
.btn-lg { padding: 1rem 2.25rem; font-size: 1rem; }

/* Label/eyebrow */
.eyebrow {
  display: inline-block;
  font-size: 0.75rem; font-weight: 700; letter-spacing: 0.12em;
  text-transform: uppercase; color: var(--green);
  margin-bottom: 1rem;
}

/* ============================================================
   NAVIGATION
   ============================================================ */
.navbar {
  position: fixed; top: 0; left: 0; right: 0; z-index: 1000;
  background: rgba(13, 27, 62, 0.96);
  backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--border-subtle);
}
.navbar-inner {
  display: flex; align-items: center; justify-content: space-between;
  padding: 0 1.5rem; height: 68px; max-width: 1280px; margin: 0 auto;
}
.nav-logo {
  display: flex; align-items: center; gap: 0.5rem;
  font-size: 1.4rem; font-weight: 800; color: var(--white);
  text-decoration: none;
}
.nav-logo span { color: var(--green); }
.nav-links { display: flex; align-items: center; gap: 0.25rem; }
.nav-link {
  padding: 0.5rem 0.875rem;
  color: var(--text-muted); font-size: 0.875rem; font-weight: 500;
  border-radius: 4px; transition: color 0.2s;
  cursor: pointer; white-space: nowrap;
}
.nav-link:hover { color: var(--white); }

/* Dropdown */
.nav-dropdown { position: relative; }
.nav-dropdown-trigger {
  display: flex; align-items: center; gap: 0.35rem;
  padding: 0.5rem 0.875rem;
  color: var(--text-muted); font-size: 0.875rem; font-weight: 500;
  border-radius: 4px; cursor: pointer; transition: color 0.2s;
  background: none; border: none;
}
.nav-dropdown-trigger:hover { color: var(--white); }
.nav-dropdown-trigger svg { transition: transform 0.2s; width: 14px; height: 14px; }
.nav-dropdown.open .nav-dropdown-trigger svg { transform: rotate(180deg); }
.nav-dropdown.open .nav-dropdown-trigger { color: var(--white); }

.dropdown-menu {
  position: absolute; top: calc(100% + 8px); left: 0;
  min-width: 200px;
  background: #1a2540;
  border: 1px solid var(--border-subtle);
  border-radius: 8px;
  box-shadow: 0 8px 32px rgba(0,0,0,0.4);
  opacity: 0; visibility: hidden;
  transform: translateY(-8px);
  transition: all 0.2s ease;
  z-index: 100;
}
.nav-dropdown.open .dropdown-menu {
  opacity: 1; visibility: visible; transform: translateY(0);
}
.dropdown-item {
  display: block; padding: 0.75rem 1.25rem;
  color: var(--text-muted); font-size: 0.875rem;
  transition: all 0.15s;
  border-radius: 4px;
}
.dropdown-item:hover { color: var(--green); background: rgba(108,194,74,0.06); }

.nav-actions { display: flex; align-items: center; gap: 0.75rem; }
.nav-cta {
  background: var(--green); color: var(--navy-dark);
  padding: 0.5rem 1.25rem;
  border-radius: 4px; font-size: 0.875rem; font-weight: 700;
  transition: background 0.2s; white-space: nowrap;
}
.nav-cta:hover { background: var(--green-dark); }

/* Mobile nav */
.nav-hamburger {
  display: none; flex-direction: column; gap: 5px;
  cursor: pointer; padding: 6px; background: none; border: none;
}
.nav-hamburger span { width: 22px; height: 2px; background: var(--white); border-radius: 2px; transition: 0.3s; }

.mobile-menu {
  display: none;
  position: fixed; inset: 68px 0 0 0; z-index: 999;
  background: var(--navy-dark);
  padding: 1.5rem;
  overflow-y: auto;
}
.mobile-menu.open { display: block; }
.mobile-menu a, .mobile-menu button {
  display: block; width: 100%; text-align: left;
  padding: 0.85rem 1rem; color: var(--text-muted);
  font-size: 1rem; background: none; border: none;
  border-bottom: 1px solid var(--border-subtle);
  cursor: pointer;
}
.mobile-menu a:hover { color: var(--white); }
.mobile-menu .mobile-cta {
  margin-top: 1.5rem;
  display: block; text-align: center;
  background: var(--green); color: var(--navy-dark);
  padding: 0.875rem; border-radius: 4px; font-weight: 700;
}

/* Page top padding */
.page-top { padding-top: 68px; }

/* ============================================================
   HERO
   ============================================================ */
.hero {
  min-height: 90vh; display: flex; align-items: center;
  background: linear-gradient(135deg, #0a1628 0%, #0f2145 50%, #0a1e3d 100%);
  position: relative; overflow: hidden;
}
.hero::before {
  content: '';
  position: absolute; inset: 0;
  background: radial-gradient(ellipse at 60% 50%, rgba(108,194,74,0.07) 0%, transparent 65%),
              radial-gradient(ellipse at 20% 80%, rgba(21,41,90,0.6) 0%, transparent 50%);
}
.hero-grid {
  position: absolute; inset: 0; opacity: 0.04;
  background-image: linear-gradient(var(--border-subtle) 1px, transparent 1px),
                    linear-gradient(90deg, var(--border-subtle) 1px, transparent 1px);
  background-size: 60px 60px;
}
.hero-content { position: relative; z-index: 2; }
.hero h1 { color: var(--white); max-width: 750px; margin-bottom: 1.25rem; }
.hero h1 span { color: var(--green); }
.hero p { font-size: 1.125rem; max-width: 580px; margin-bottom: 2rem; color: var(--text-muted); }
.hero-actions { display: flex; gap: 1rem; flex-wrap: wrap; }
.hero-badge {
  display: inline-flex; align-items: center; gap: 0.5rem;
  background: rgba(108,194,74,0.12); border: 1px solid rgba(108,194,74,0.25);
  color: var(--green); padding: 0.35rem 0.875rem;
  border-radius: 50px; font-size: 0.75rem; font-weight: 600;
  margin-bottom: 1.5rem; letter-spacing: 0.05em;
}
.hero-badge::before { content: '●'; font-size: 0.5rem; }

/* Sub-hero */
.sub-hero {
  min-height: 50vh; display: flex; align-items: center;
  background: linear-gradient(135deg, #0a1628 0%, #0f2145 60%, #0a1e3d 100%);
  position: relative; overflow: hidden;
}
.sub-hero::before {
  content: '';
  position: absolute; inset: 0;
  background: radial-gradient(ellipse at 50% 50%, rgba(108,194,74,0.06) 0%, transparent 70%);
}
.sub-hero-content { position: relative; z-index: 2; }
.sub-hero h1 { color: var(--white); max-width: 700px; margin-bottom: 1rem; }
.sub-hero p { font-size: 1.05rem; max-width: 550px; color: var(--text-muted); }

/* ============================================================
   PRODUCT BANNER
   ============================================================ */
.product-banner {
  background: linear-gradient(90deg, var(--green) 0%, #52A034 100%);
  padding: 1.25rem 0;
}
.product-banner-inner {
  display: flex; align-items: center; justify-content: space-between;
  gap: 1rem; flex-wrap: wrap;
}
.product-banner-text { display: flex; align-items: center; gap: 1rem; }
.product-banner-label {
  background: rgba(0,0,0,0.15); color: var(--navy-dark);
  padding: 0.25rem 0.75rem; border-radius: 50px;
  font-size: 0.7rem; font-weight: 700; letter-spacing: 0.1em; text-transform: uppercase;
}
.product-banner h3 { color: var(--navy-dark); font-size: 1.1rem; }
.product-banner .btn-banner {
  background: var(--navy-dark); color: var(--white);
  padding: 0.5rem 1.25rem; border-radius: 4px;
  font-size: 0.875rem; font-weight: 600; white-space: nowrap;
}
.product-banner .btn-banner:hover { background: #0a1220; }

/* ============================================================
   USE CASES
   ============================================================ */
.use-cases-grid {
  display: grid; grid-template-columns: repeat(auto-fill, minmax(320px, 1fr));
  gap: 1.5rem; margin-top: 3rem;
}
.use-case-card {
  background: var(--surface-2);
  border: 1px solid var(--border-subtle);
  border-radius: 10px;
  padding: 2rem;
  cursor: pointer;
  transition: all 0.25s ease;
  position: relative; overflow: hidden;
}
.use-case-card::before {
  content: '';
  position: absolute; top: 0; left: 0; right: 0; height: 3px;
  background: var(--green); opacity: 0; transition: opacity 0.25s;
}
.use-case-card:hover { border-color: rgba(108,194,74,0.35); transform: translateY(-3px); box-shadow: 0 8px 32px rgba(0,0,0,0.3); }
.use-case-card:hover::before { opacity: 1; }
.use-case-icon {
  width: 48px; height: 48px;
  background: rgba(108,194,74,0.1); border-radius: 10px;
  display: flex; align-items: center; justify-content: center;
  margin-bottom: 1.25rem; color: var(--green); font-size: 1.5rem;
}
.use-case-card h4 { color: var(--white); margin-bottom: 0.75rem; }
.use-case-card p { font-size: 0.9rem; }

/* ============================================================
   INDUSTRY TABS
   ============================================================ */
.industry-section { background: var(--surface); }
.tab-nav {
  display: flex; gap: 0.25rem; flex-wrap: wrap;
  border-bottom: 1px solid var(--border-subtle);
  margin-bottom: 2.5rem;
}
.tab-btn {
  padding: 0.75rem 1.25rem;
  background: none; border: none; border-bottom: 2px solid transparent;
  color: var(--gray-mid); font-size: 0.875rem; font-weight: 600;
  cursor: pointer; transition: all 0.2s; margin-bottom: -1px;
}
.tab-btn:hover { color: var(--white); }
.tab-btn.active { color: var(--green); border-bottom-color: var(--green); }
.tab-panel { display: none; animation: fadeIn 0.3s ease; }
.tab-panel.active { display: block; }

@keyframes fadeIn { from { opacity: 0; transform: translateY(6px); } to { opacity: 1; transform: none; } }

.industry-content {
  display: grid; grid-template-columns: 1fr 1fr;
  gap: 3rem; align-items: center;
}
.industry-solutions { list-style: none; }
.industry-solutions li {
  display: flex; align-items: flex-start; gap: 0.75rem;
  padding: 0.875rem 0; border-bottom: 1px solid var(--border-subtle);
  color: var(--text-muted); font-size: 0.925rem;
}
.industry-solutions li::before {
  content: ''; width: 6px; height: 6px; background: var(--green);
  border-radius: 50%; margin-top: 0.45rem; flex-shrink: 0;
}
.industry-visual {
  background: var(--surface-2);
  border: 1px solid var(--border-subtle);
  border-radius: 12px; padding: 2rem;
  min-height: 280px; display: flex; flex-direction: column; justify-content: center;
}
.industry-stat { text-align: center; padding: 1rem; }
.industry-stat .big-num { font-size: 3.5rem; font-weight: 800; color: var(--green); line-height: 1; }
.industry-stat p { font-size: 0.85rem; margin-top: 0.5rem; }

/* ============================================================
   PLATFORM DIAGRAM
   ============================================================ */
.diagram-section { background: var(--surface); }
.platform-diagram {
  display: grid; grid-template-columns: repeat(3, 1fr); gap: 0;
  border: 1px solid var(--border-subtle); border-radius: 12px; overflow: hidden;
  margin-top: 3rem;
}
.diagram-pillar {
  padding: 2.5rem 2rem; border-right: 1px solid var(--border-subtle);
  position: relative;
}
.diagram-pillar:last-child { border-right: none; }
.pillar-num {
  font-size: 0.7rem; font-weight: 700; letter-spacing: 0.1em;
  text-transform: uppercase; color: var(--green); margin-bottom: 1rem;
}
.diagram-pillar h4 { color: var(--white); margin-bottom: 0.75rem; }
.diagram-pillar p { font-size: 0.875rem; }
.pillar-icon {
  font-size: 2.5rem; margin-bottom: 1.25rem;
  background: linear-gradient(135deg, var(--green) 0%, #52A034 100%);
  -webkit-background-clip: text; -webkit-text-fill-color: transparent;
}
.diagram-center {
  display: none; /* replaced by grid layout */
}
.diagram-connector {
  background: rgba(108,194,74,0.06);
}

/* SVG diagram */
.ecosystem-svg { width: 100%; max-width: 800px; margin: 3rem auto 0; display: block; }

/* ============================================================
   COMPANY CULTURE
   ============================================================ */
.culture-section {
  background: linear-gradient(135deg, #0f1f40 0%, #152960 100%);
  position: relative; overflow: hidden;
}
.culture-section::before {
  content: '';
  position: absolute; top: -50%; right: -10%;
  width: 600px; height: 600px;
  background: radial-gradient(ellipse, rgba(108,194,74,0.08) 0%, transparent 65%);
}
.culture-inner {
  display: grid; grid-template-columns: 1fr 1fr; gap: 4rem; align-items: center;
  position: relative; z-index: 2;
}
.culture-stats { display: grid; grid-template-columns: 1fr 1fr; gap: 1.5rem; margin-top: 2rem; }
.culture-stat {
  background: rgba(255,255,255,0.04); border: 1px solid var(--border-subtle);
  border-radius: 8px; padding: 1.25rem;
}
.culture-stat .num { font-size: 2rem; font-weight: 800; color: var(--green); }
.culture-stat p { font-size: 0.8rem; margin-top: 0.25rem; }

/* ============================================================
   RENEWABLES CTA
   ============================================================ */
.renewables-cta {
  background: var(--navy);
  border-top: 1px solid var(--border-subtle);
}
.renewables-inner {
  display: grid; grid-template-columns: 1fr auto; gap: 2rem; align-items: center;
}
.renewables-inner h2 { color: var(--white); }
.renewables-inner p { max-width: 500px; margin-top: 0.75rem; }

/* ============================================================
   PLATFORM BENEFITS
   ============================================================ */
.benefits-grid {
  display: grid; grid-template-columns: repeat(auto-fill, minmax(300px, 1fr));
  gap: 1.5rem; margin-top: 3rem;
}
.benefit-card {
  background: var(--surface-2); border: 1px solid var(--border-subtle);
  border-radius: 10px; padding: 2rem;
  transition: border-color 0.2s;
}
.benefit-card:hover { border-color: rgba(108,194,74,0.3); }
.benefit-icon {
  width: 44px; height: 44px; border-radius: 8px;
  background: rgba(108,194,74,0.1);
  display: flex; align-items: center; justify-content: center;
  font-size: 1.25rem; margin-bottom: 1rem; color: var(--green);
}
.benefit-card h4 { color: var(--white); margin-bottom: 0.5rem; }
.benefit-card p { font-size: 0.875rem; }

/* ============================================================
   STATS - Circular
   ============================================================ */
.stats-section { background: var(--surface); }
.stats-grid {
  display: grid; grid-template-columns: repeat(3, 1fr); gap: 2rem;
  margin-top: 3rem;
}
.stat-circle {
  display: flex; flex-direction: column; align-items: center; text-align: center;
}
.circle-outer {
  width: 160px; height: 160px; position: relative; margin-bottom: 1.5rem;
}
.circle-svg { width: 100%; height: 100%; transform: rotate(-90deg); }
.circle-track { fill: none; stroke: rgba(255,255,255,0.08); stroke-width: 8; }
.circle-fill { fill: none; stroke: var(--green); stroke-width: 8; stroke-linecap: round; transition: stroke-dashoffset 1.2s ease; }
.circle-text {
  position: absolute; inset: 0;
  display: flex; flex-direction: column; align-items: center; justify-content: center;
}
.circle-text .big { font-size: 2rem; font-weight: 800; color: var(--white); line-height: 1; }
.stat-circle h4 { color: var(--white); margin-bottom: 0.5rem; }
.stat-circle p { font-size: 0.875rem; max-width: 200px; }

/* ============================================================
   IMPLEMENTATION TIMELINE
   ============================================================ */
.timeline-items { margin-top: 3rem; display: flex; flex-direction: column; gap: 2rem; }
.timeline-item {
  background: var(--surface-2); border: 1px solid var(--border-subtle);
  border-radius: 10px; padding: 2rem;
}
.timeline-header { display: flex; align-items: center; justify-content: space-between; margin-bottom: 1rem; }
.timeline-duration {
  font-size: 1.5rem; font-weight: 800; color: var(--green);
}
.timeline-label { color: var(--white); font-weight: 600; }
.progress-bar { height: 6px; background: rgba(255,255,255,0.08); border-radius: 3px; overflow: hidden; }
.progress-fill { height: 100%; background: linear-gradient(90deg, var(--green) 0%, #52A034 100%); border-radius: 3px; transition: width 1s ease; }

/* ============================================================
   ACCORDION
   ============================================================ */
.accordion { margin-top: 3rem; }
.accordion-item {
  border-bottom: 1px solid var(--border-subtle);
}
.accordion-header {
  display: flex; align-items: center; justify-content: space-between;
  padding: 1.5rem 0; cursor: pointer;
  background: none; border: none; width: 100%; text-align: left;
  color: var(--white); font-size: 1.1rem; font-weight: 600;
  transition: color 0.2s;
}
.accordion-header:hover { color: var(--green); }
.accordion-header.active { color: var(--green); }
.accordion-icon {
  width: 28px; height: 28px; border-radius: 50%;
  background: rgba(108,194,74,0.1); border: 1px solid rgba(108,194,74,0.25);
  display: flex; align-items: center; justify-content: center;
  color: var(--green); font-size: 1rem; transition: transform 0.3s;
  flex-shrink: 0;
}
.accordion-header.active .accordion-icon { transform: rotate(45deg); }
.accordion-body {
  max-height: 0; overflow: hidden; transition: max-height 0.35s ease;
}
.accordion-body-inner { padding: 0 0 1.5rem; color: var(--text-muted); font-size: 0.95rem; line-height: 1.7; }

/* ============================================================
   DATA LIFECYCLE DIAGRAM
   ============================================================ */
.lifecycle-diagram {
  margin-top: 3rem;
  display: grid; grid-template-columns: repeat(3, 1fr);
  gap: 0; position: relative;
}
.lifecycle-phase {
  padding: 2.5rem 2rem;
  background: var(--surface-2);
  border: 1px solid var(--border-subtle);
  margin: 0 -1px -1px 0;
  position: relative;
}
.lifecycle-phase:last-child { margin-right: 0; }
.phase-num {
  width: 36px; height: 36px; border-radius: 50%;
  background: var(--green); color: var(--navy-dark);
  display: flex; align-items: center; justify-content: center;
  font-weight: 800; font-size: 0.875rem; margin-bottom: 1rem;
}
.lifecycle-steps { list-style: none; margin-top: 1rem; }
.lifecycle-steps li {
  padding: 0.4rem 0; color: var(--text-muted); font-size: 0.85rem;
  border-bottom: 1px solid var(--border-subtle);
  display: flex; align-items: center; gap: 0.5rem;
}
.lifecycle-steps li::before { content: '→'; color: var(--green); font-size: 0.75rem; }

/* ============================================================
   TESTIMONIALS / CAROUSEL
   ============================================================ */
.testimonials-section { background: var(--surface); }
.carousel-wrapper { position: relative; margin-top: 3rem; overflow: hidden; }
.carousel-track { display: flex; transition: transform 0.45s ease; }
.testimonial-card {
  min-width: 100%; padding: 2.5rem;
  background: var(--surface-2); border: 1px solid var(--border-subtle);
  border-radius: 12px;
}
.quote-mark { font-size: 4rem; color: var(--green); line-height: 0.8; margin-bottom: 1rem; opacity: 0.5; }
.testimonial-card blockquote { font-size: 1.1rem; color: var(--white); line-height: 1.7; font-style: italic; }
.testimonial-meta { margin-top: 1.5rem; display: flex; align-items: center; gap: 1rem; }
.testimonial-avatar {
  width: 48px; height: 48px; border-radius: 50%;
  background: linear-gradient(135deg, var(--green), var(--navy));
  display: flex; align-items: center; justify-content: center;
  font-weight: 700; color: var(--white);
}
.testimonial-info { color: var(--text-muted); font-size: 0.875rem; }
.testimonial-info strong { color: var(--white); display: block; }
.carousel-dots { display: flex; gap: 0.5rem; justify-content: center; margin-top: 1.5rem; }
.carousel-dot {
  width: 8px; height: 8px; border-radius: 50%;
  background: rgba(255,255,255,0.2); cursor: pointer;
  transition: all 0.2s; border: none; padding: 0;
}
.carousel-dot.active { background: var(--green); width: 24px; border-radius: 4px; }

/* ============================================================
   SECURITY
   ============================================================ */
.security-features-grid {
  display: grid; grid-template-columns: repeat(auto-fill, minmax(320px, 1fr));
  gap: 1.5rem; margin-top: 2.5rem;
}
.security-card {
  background: var(--surface-2); border: 1px solid var(--border-subtle);
  border-radius: 10px; padding: 2rem;
  transition: border-color 0.2s;
}
