   ============================================================ */
.demo-page {
  background: linear-gradient(135deg, #0a1628 0%, #0f2145 100%);
  min-height: 100vh;
}
.demo-layout {
  display: grid; grid-template-columns: 1fr 1fr; gap: 5rem; align-items: start;
  padding: 6rem 0 5rem;
}
.demo-form-card {
  background: var(--surface-2); border: 1px solid var(--border-subtle);
  border-radius: 16px; padding: 3rem;
}
.form-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 1.25rem; margin-top: 2rem; }
.form-grid .full { grid-column: 1 / -1; }
.form-group { display: flex; flex-direction: column; gap: 0.4rem; }
.form-group label { font-size: 0.8rem; font-weight: 600; color: var(--text-muted); letter-spacing: 0.04em; text-transform: uppercase; }
.form-control {
  background: var(--surface-3); border: 1px solid var(--border-subtle);
  border-radius: 6px; padding: 0.75rem 1rem;
  color: var(--white); font-size: 0.9rem; font-family: var(--font);
  transition: border-color 0.2s; outline: none;
}
.form-control:focus { border-color: var(--green); }
.form-control::placeholder { color: var(--gray-mid); }
textarea.form-control { resize: vertical; min-height: 100px; }
select.form-control { appearance: none; cursor: pointer; }
.form-error { color: #f87171; font-size: 0.75rem; display: none; }
.form-control.invalid { border-color: #f87171; }
.form-control.invalid + .form-error { display: block; }
.form-submit { margin-top: 1.5rem; width: 100%; text-align: center; }

.support-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 1.5rem; margin-top: 2rem; }
.support-card {
  background: var(--surface-2); border: 1px solid var(--border-subtle);
  border-radius: 10px; padding: 1.5rem; text-align: center;
}
.support-card .flag { font-size: 2rem; margin-bottom: 0.75rem; }
.support-card h4 { color: var(--white); font-size: 0.95rem; margin-bottom: 0.5rem; }
.support-card p { font-size: 0.8rem; }

