   COMPLIANCE CTA
   ============================================================ */
.compliance-cta {
  background: linear-gradient(135deg, #0e2255 0%, #152f68 100%);
  border: 1px solid rgba(108,194,74,0.2);
  border-radius: 16px; padding: 3.5rem;
  text-align: center; margin-top: 4rem;
