.compliance-cta h2 { color: var(--white); margin-bottom: 1rem; }
.compliance-cta p { max-width: 500px; margin: 0 auto 2rem; }
.badge-row { display: flex; justify-content: center; flex-wrap: wrap; gap: 0.5rem; margin-bottom: 2rem; }

