.footer-bottom p { color: var(--gray-mid); font-size: 0.8rem; }
.footer-login-links { display: flex; gap: 1rem; flex-wrap: wrap; }
.footer-login-links a { color: var(--gray-mid); font-size: 0.8rem; transition: color 0.15s; }
.footer-login-links a:hover { color: var(--green); }

/* ============================================================
   COOKIE BANNER
