.cookie-banner {
  position: fixed; bottom: 0; left: 0; right: 0; z-index: 2000;
  background: #1a2540; border-top: 1px solid var(--border-subtle);
  padding: 1.25rem 1.5rem;
  display: flex; align-items: center; justify-content: space-between;
  gap: 1.5rem; flex-wrap: wrap;
  transform: translateY(100%); transition: transform 0.4s ease;
  box-shadow: 0 -4px 24px rgba(0,0,0,0.3);
}
.cookie-banner.visible { transform: translateY(0); }
.cookie-text { font-size: 0.875rem; color: var(--text-muted); max-width: 600px; }
.cookie-text a { color: var(--green); }
.cookie-actions { display: flex; gap: 0.75rem; flex-shrink: 0; }
.cookie-btn {
  padding: 0.5rem 1.25rem; border-radius: 4px;
  font-size: 0.875rem; font-weight: 600; cursor: pointer;
  transition: all 0.2s; border: 2px solid transparent;
}
.cookie-accept { background: var(--green); color: var(--navy-dark); }
.cookie-accept:hover { background: var(--green-dark); }
.cookie-decline { background: transparent; color: var(--text-muted); border-color: var(--border-subtle); }
.cookie-decline:hover { border-color: var(--gray-mid); color: var(--white); }

/* ============================================================
   FORM SUCCESS
   ============================================================ */
.form-success {
