}
.form-success.show { display: block; }
.form-success-icon { font-size: 3.5rem; color: var(--green); margin-bottom: 1rem; }
.form-success h3 { color: var(--white); margin-bottom: 0.75rem; }

/* ============================================================
   UTILITIES
