.text-white { color: var(--white); }
.mt-1 { margin-top: 0.5rem; }
.mt-2 { margin-top: 1rem; }
.mt-3 { margin-top: 1.5rem; }
.mt-4 { margin-top: 2rem; }
.mt-6 { margin-top: 3rem; }
.mb-1 { margin-bottom: 0.5rem; }
.mb-2 { margin-bottom: 1rem; }
.mb-3 { margin-bottom: 1.5rem; }
.section-header { max-width: 680px; }
.section-header.centered { margin: 0 auto; text-align: center; }
.section-header h2 { color: var(--white); margin-bottom: 1rem; }
.section-header p { color: var(--text-muted); font-size: 1rem; }
.divider { height: 1px; background: var(--border-subtle); margin: 2rem 0; }
.badge { display: inline-flex; align-items: center; gap: 0.4rem; background: rgba(108,194,74,0.1); border: 1px solid rgba(108,194,74,0.25); color: var(--green); padding: 0.3rem 0.75rem; border-radius: 4px; font-size: 0.75rem; font-weight: 600; }

/* ============================================================
