  .platform-diagram { grid-template-columns: 1fr; }
  .diagram-pillar { border-right: none; border-bottom: 1px solid var(--border-subtle); }
  .diagram-pillar:last-child { border-bottom: none; }
  .culture-inner { grid-template-columns: 1fr; gap: 2rem; }
  .demo-layout { grid-template-columns: 1fr; gap: 3rem; }
  .lifecycle-diagram { grid-template-columns: 1fr; }
  .renewables-inner { grid-template-columns: 1fr; }
  .industry-content { grid-template-columns: 1fr; }
